/**
 * File contents for the "Harden structured extraction from freight documents" work sample.
 * All data is synthetic. scripts/test-extraction-structured-output.ts runs these files for real.
 */

export const STARTER_README = "# freight-intake\n\nNightly intake for scanned freight documents at Corvane Freight. Carriers send bills of\nlading and delivery receipts; OCR turns each scan into text, and this pipeline asks the\nextraction provider (a hosted language model behind our internal gateway) to return the\nshipment fields as JSON. Stored records feed billing and dispatch. Documents the pipeline\ncannot handle go to the manual review queue, where the intake team keys them in by hand.\n\n## Layout\n\n- `src/intake.js`: `createIntake({ transport, store, reviewQueue, sleep })` with\n  `processDocument(document)` and `runBatch(documents)`.\n- `src/schema.js`: `SHIPMENT_FIELDS`, the documented shipment record.\n- `src/prompt.js`: builds the extraction request for one document.\n- `src/store.js`: in-memory record store and review queue.\n- `src/recorded-transport.js`: replays recorded provider responses instead of calling the provider.\n- `scripts/replay-batch.js`: replays the 2026-09-22 nightly batch.\n- `fixtures/documents.json`, `fixtures/recorded_responses.json`: that batch (synthetic).\n- `test/public.test.js`: tests.\n\n## The provider gateway\n\n`transport.send({ documentId, prompt })` resolves to `{ status, headers, body }`, where\n`body` is the model's raw text and header names are lowercase. It rejects when the\nrequest times out or the connection fails.\n\n- `200`: the model answered. The body is supposed to be one JSON object, but it is\n  model output and is not guaranteed to be valid.\n- `429`: rate limited. `retry-after` holds the number of seconds to wait.\n- `5xx`: the gateway or the model failed.\n- Other `4xx`: the request itself was rejected, for example a document over the page limit.\n\nNothing in this repository calls the provider for real. Tests and the replay script use\nrecorded responses and a `sleep` that does not wait.\n\n## Running\n\nNode.js 22 or newer, no npm packages. From the project root:\n\n```\nnode --test test/public.test.js\nnode scripts/replay-batch.js\n```\n";

export const STARTER_SCHEMA = "/**\n * The shipment record the intake pipeline stores, as agreed with billing and dispatch.\n * The extraction prompt is built from this list, and downstream systems read exactly these fields.\n */\nexport const SHIPMENT_FIELDS = [\n  { name: \"shipment_id\", type: \"string\", required: true, rule: 'Our shipment number: \"SHP-\" followed by 6 digits, e.g. \"SHP-204412\".' },\n  { name: \"carrier_scac\", type: \"string\", required: true, rule: \"Carrier SCAC code: 2 to 4 uppercase letters.\" },\n  { name: \"pickup_date\", type: \"string\", required: true, rule: \"Pickup date as YYYY-MM-DD. Must be a real calendar date.\" },\n  { name: \"delivery_date\", type: \"string\", required: false, rule: \"Delivery date as YYYY-MM-DD, or null when not delivered yet. Not before pickup_date.\" },\n  { name: \"pieces\", type: \"integer\", required: true, rule: \"Number of handling units, 1 to 999.\" },\n  { name: \"weight_kg\", type: \"number\", required: true, rule: \"Total weight in kilograms, greater than 0 and at most 30000.\" },\n  { name: \"hazmat\", type: \"boolean\", required: true, rule: \"true when the document declares dangerous goods, otherwise false.\" },\n];\n";

export const STARTER_PROMPT = "import { SHIPMENT_FIELDS } from \"./schema.js\";\n\nconst INSTRUCTIONS = [\n  \"You extract shipment data from a freight document (bill of lading or delivery receipt).\",\n  \"Reply with one JSON object and nothing else. Use exactly these fields:\",\n];\n\n/** The request body sent to the extraction provider for one document. */\nexport function buildExtractionRequest(document) {\n  const fieldLines = SHIPMENT_FIELDS.map((f) => `- ${f.name} (${f.type}${f.required ? \", required\" : \", optional\"}): ${f.rule}`);\n  const prompt = [...INSTRUCTIONS, ...fieldLines, \"\", \"Document:\", document.text].join(\"\\n\");\n  return { documentId: document.id, prompt };\n}\n";

export const STARTER_STORE = "/**\n * In-memory stand-ins for the shipments table and the manual review queue.\n * Production uses the same two methods on database-backed implementations.\n */\nexport function createRecordStore() {\n  const records = new Map();\n  return {\n    save(documentId, record) {\n      records.set(documentId, record);\n    },\n    get(documentId) {\n      return records.get(documentId);\n    },\n    all() {\n      return [...records.entries()].map(([documentId, record]) => ({ documentId, record }));\n    },\n  };\n}\n\nexport function createReviewQueue() {\n  const items = [];\n  return {\n    add(item) {\n      items.push(item);\n    },\n    all() {\n      return [...items];\n    },\n  };\n}\n";

export const STARTER_INTAKE = "import { buildExtractionRequest } from \"./prompt.js\";\n\n/**\n * Document intake: sends each document to the extraction provider and stores the shipment record.\n *\n * deps.transport.send(request) -> Promise<{ status, headers, body }>; rejects on a timeout or connection error.\n * deps.store.save(documentId, record)\n * deps.reviewQueue.add({ documentId, reason, fields, attempts })\n * deps.sleep(ms) -> Promise<void>\n */\nexport function createIntake({ transport, store, reviewQueue, sleep }) {\n  async function processDocument(document) {\n    const response = await transport.send(buildExtractionRequest(document));\n    if (response.status !== 200) {\n      throw new Error(`extraction failed for ${document.id}: HTTP ${response.status}`);\n    }\n    const record = JSON.parse(response.body);\n    store.save(document.id, record);\n    return { documentId: document.id, outcome: \"stored\", attempts: 1 };\n  }\n\n  async function runBatch(documents) {\n    const results = [];\n    for (const document of documents) {\n      results.push(await processDocument(document));\n    }\n    return results;\n  }\n\n  return { processDocument, runBatch };\n}\n";

export const STARTER_RECORDED_TRANSPORT = "/**\n * Replays provider responses captured from a real batch, so the pipeline can run\n * without calling the provider. recordings: { [documentId]: Array<Response | { error: \"timeout\" }> }.\n * Each send() for a document returns that document's next recorded response.\n */\nexport function createRecordedTransport(recordings) {\n  const calls = [];\n  const position = new Map();\n  return {\n    calls,\n    async send(request) {\n      calls.push(request.documentId);\n      const sequence = recordings[request.documentId] ?? [];\n      const i = position.get(request.documentId) ?? 0;\n      position.set(request.documentId, i + 1);\n      const recorded = sequence[i];\n      if (!recorded) throw new Error(`no recorded response ${i + 1} for ${request.documentId}`);\n      if (recorded.error === \"timeout\") {\n        const error = new Error(\"provider did not respond within 20 s\");\n        error.name = \"TimeoutError\";\n        throw error;\n      }\n      return { status: recorded.status, headers: { ...(recorded.headers ?? {}) }, body: recorded.body ?? \"\" };\n    },\n  };\n}\n";

export const STARTER_REPLAY = "// Replays the 2026-09-22 nightly batch against the recorded provider responses.\n// Run from the project root:  node scripts/replay-batch.js\nimport { readFileSync } from \"node:fs\";\nimport { createIntake } from \"../src/intake.js\";\nimport { createRecordedTransport } from \"../src/recorded-transport.js\";\nimport { createRecordStore, createReviewQueue } from \"../src/store.js\";\n\nconst { documents } = JSON.parse(readFileSync(new URL(\"../fixtures/documents.json\", import.meta.url), \"utf8\"));\nconst { responses } = JSON.parse(readFileSync(new URL(\"../fixtures/recorded_responses.json\", import.meta.url), \"utf8\"));\n\nconst transport = createRecordedTransport(responses);\nconst store = createRecordStore();\nconst reviewQueue = createReviewQueue();\nconst waits = [];\nconst sleep = async (ms) => {\n  waits.push(ms);\n};\n\nconst intake = createIntake({ transport, store, reviewQueue, sleep });\ntry {\n  const results = await intake.runBatch(documents);\n  console.log(\"Results\");\n  for (const r of results) console.log(`  ${r.documentId}  ${r.outcome}  attempts=${r.attempts}`);\n} catch (error) {\n  console.log(`Batch stopped: ${error instanceof Error ? error.message : String(error)}`);\n}\n\nconsole.log(`\\nProvider calls: ${transport.calls.length}   waits (ms): ${waits.join(\", \") || \"none\"}`);\nconsole.log(\"\\nStored records\");\nfor (const { documentId, record } of store.all()) console.log(`  ${documentId}  ${JSON.stringify(record)}`);\nconsole.log(\"\\nManual review queue\");\nfor (const item of reviewQueue.all()) console.log(`  ${JSON.stringify(item)}`);\n";

