export const TEST_PUBLIC = "import test from \"node:test\";\nimport assert from \"node:assert/strict\";\nimport { readFileSync } from \"node:fs\";\nimport { createIntake } from \"../src/intake.js\";\nimport { createRecordedTransport } from \"../src/recorded-transport.js\";\nimport { createRecordStore, createReviewQueue } from \"../src/store.js\";\n\nconst { documents } = JSON.parse(readFileSync(new URL(\"../fixtures/documents.json\", import.meta.url), \"utf8\"));\nconst { responses } = JSON.parse(readFileSync(new URL(\"../fixtures/recorded_responses.json\", import.meta.url), \"utf8\"));\n\nfunction setup(recordings = responses) {\n  const transport = createRecordedTransport(recordings);\n  const store = createRecordStore();\n  const reviewQueue = createReviewQueue();\n  const waits = [];\n  const sleep = async (ms) => {\n    waits.push(ms);\n  };\n  return { intake: createIntake({ transport, store, reviewQueue, sleep }), transport, store, reviewQueue, waits };\n}\n\nconst doc = (id) => documents.find((d) => d.id === id);\n\ntest(\"nightly batch replay: every document gets a result and nothing invalid is stored\", async () => {\n  const { intake, store, reviewQueue } = setup();\n\n  const results = await intake.runBatch(documents);\n\n  assert.deepEqual(results.map((r) => r.documentId), documents.map((d) => d.id));\n  const stored = store.all().map((s) => s.documentId).sort();\n  assert.deepEqual(stored, [\"DOC-0412\", \"DOC-0413\", \"DOC-0414\", \"DOC-0415\", \"DOC-0421\"]);\n  const reviewed = reviewQueue.all().map((i) => i.documentId).sort();\n  assert.deepEqual(reviewed, [\"DOC-0416\", \"DOC-0417\", \"DOC-0418\", \"DOC-0419\", \"DOC-0420\", \"DOC-0422\", \"DOC-0423\"]);\n});\n\ntest(\"a code-fenced response is stored as a clean record\", async () => {\n  const { intake, store } = setup();\n\n  const result = await intake.processDocument(doc(\"DOC-0413\"));\n\n  assert.equal(result.outcome, \"stored\");\n  assert.deepEqual(store.get(\"DOC-0413\"), {\n    shipment_id: \"SHP-204413\",\n    carrier_scac: \"KSTR\",\n    pickup_date: \"2026-09-20\",\n    delivery_date: \"2026-09-22\",\n    pieces: 3,\n    weight_kg: 412.5,\n    hazmat: false,\n  });\n});\n\ntest(\"a rate-limited request is retried after the Retry-After delay\", async () => {\n  const { intake, store, transport, waits } = setup();\n\n  const result = await intake.processDocument(doc(\"DOC-0415\"));\n\n  assert.deepEqual(result, { documentId: \"DOC-0415\", outcome: \"stored\", attempts: 2 });\n  assert.deepEqual(waits, [7000]);\n  assert.equal(transport.calls.length, 2);\n  assert.equal(store.get(\"DOC-0415\").hazmat, true);\n});\n\ntest(\"a weight with units goes to manual review instead of the store\", async () => {\n  const { intake, store, reviewQueue } = setup();\n\n  const result = await intake.processDocument(doc(\"DOC-0416\"));\n\n  assert.equal(result.outcome, \"manual_review\");\n  assert.equal(store.get(\"DOC-0416\"), undefined);\n  assert.deepEqual(reviewQueue.all(), [{ documentId: \"DOC-0416\", reason: \"invalid_fields\", fields: [\"weight_kg\"], attempts: 1 }]);\n});\n";

export const TEST_EVALUATION = "import test from \"node:test\";\nimport assert from \"node:assert/strict\";\nimport { createIntake } from \"../src/intake.js\";\n\n// Held-out documents and provider responses. None of these appear in the candidate's fixtures.\nconst TIMEOUT = \"timeout\";\nconst FENCE = \"`\".repeat(3);\n\nconst VALID = {\n  shipment_id: \"SHP-310001\",\n  carrier_scac: \"QRVL\",\n  pickup_date: \"2026-10-01\",\n  delivery_date: \"2026-10-03\",\n  pieces: 40,\n  weight_kg: 12500.75,\n  hazmat: true,\n};\n\nconst ok = (value) => ({ status: 200, headers: { \"content-type\": \"application/json\" }, body: typeof value === \"string\" ? value : JSON.stringify(value) });\nconst status = (code, headers = {}) => ({ status: code, headers: { \"content-type\": \"application/json\", ...headers }, body: JSON.stringify({ error: `http_${code}` }) });\n\nfunction document(id) {\n  return { id, carrier: \"QRVL\", received: \"2026-10-03T22:10:00Z\", text: `DELIVERY RECEIPT\\nRef ${id}\\nQuarry Valley Freight (QRVL)` };\n}\n\n/**\n * scripts: an array of steps for every document, or { [documentId]: steps }.\n * Once a document's steps run out, its last step repeats.\n */\nfunction harness(scripts) {\n  const calls = [];\n  const waits = [];\n  const saved = [];\n  const reviews = [];\n  const perDocument = new Map();\n  const transport = {\n    async send(request) {\n      calls.push(request.documentId);\n      const steps = Array.isArray(scripts) ? scripts : scripts[request.documentId];\n      const n = perDocument.get(request.documentId) ?? 0;\n      perDocument.set(request.documentId, n + 1);\n      const step = steps[Math.min(n, steps.length - 1)];\n      if (step === TIMEOUT) {\n        const error = new Error(\"provider timed out\");\n        error.name = \"TimeoutError\";\n        throw error;\n      }\n      return { status: step.status, headers: { ...step.headers }, body: step.body };\n    },\n  };\n  const store = {\n    save(documentId, record) {\n      saved.push({ documentId, record: structuredClone(record) });\n    },\n    get(documentId) {\n      return saved.find((s) => s.documentId === documentId)?.record;\n    },\n    all() {\n      return saved.map((s) => ({ ...s }));\n    },\n  };\n  const reviewQueue = {\n    add(item) {\n      reviews.push(structuredClone(item));\n    },\n    all() {\n      return [...reviews];\n    },\n  };\n  const sleep = async (ms) => {\n    waits.push(ms);\n  };\n  return { intake: createIntake({ transport, store, reviewQueue, sleep }), calls, waits, saved, reviews };\n}\n\nasync function expectInvalidFields(body, fields, label) {\n  const h = harness([ok(body)]);\n  const result = await h.intake.processDocument(document(\"DOC-9100\"));\n  assert.equal(result.outcome, \"manual_review\", `${label}: expected manual review, got ${result.outcome}`);\n  assert.deepEqual(h.saved, [], `${label}: an invalid record was stored`);\n  assert.equal(h.reviews.length, 1, `${label}: expected one review item`);\n  assert.equal(h.reviews[0].reason, \"invalid_fields\", `${label}: reason`);\n  assert.deepEqual([...h.reviews[0].fields].sort(), [...fields].sort(), `${label}: fields`);\n}\n\ntest(\"stores a valid response once, with exactly the schema fields\", async () => {\n  const h = harness([ok({ ...VALID, confidence: 0.88, notes: \"two pallets shrink-wrapped together\" })]);\n  const result = await h.intake.processDocument(document(\"DOC-9001\"));\n  assert.deepEqual(result, { documentId: \"DOC-9001\", outcome: \"stored\", attempts: 1 });\n  assert.deepEqual(h.saved, [{ documentId: \"DOC-9001\", record: VALID }]);\n  assert.deepEqual(h.reviews, []);\n\n  const { delivery_date: _omitted, ...notDelivered } = VALID;\n  void _omitted;\n  const h2 = harness([ok(notDelivered)]);\n  await h2.intake.processDocument(document(\"DOC-9002\"));\n  assert.deepEqual(h2.saved, [{ documentId: \"DOC-9002\", record: { ...VALID, delivery_date: null } }]);\n});\n\ntest(\"repairs only a surrounding code fence and plain numeric strings\", async () => {\n  const pretty = JSON.stringify({ ...VALID, pieces: \"40\", weight_kg: \"12500.75\" }, null, 2);\n  for (const body of [`${FENCE}json\\n${pretty}\\n${FENCE}`, `${FENCE}\\n${pretty}\\n${FENCE}`, `\\n  ${FENCE}json\\n${pretty}\\n${FENCE}  \\n`]) {\n    const h = harness([ok(body)]);\n    const result = await h.intake.processDocument(document(\"DOC-9010\"));\n    assert.equal(result.outcome, \"stored\", `not stored: ${JSON.stringify(body.slice(0, 40))}`);\n    assert.deepEqual(h.saved[0].record, VALID);\n  }\n});\n\ntest(\"output that is not a JSON object goes to manual review as invalid_json\", async () => {\n  const truncated = JSON.stringify(VALID).slice(0, 70);\n  for (const body of [truncated, `Here is the extracted data: ${JSON.stringify(VALID)}`, \"[]\", \"\", \"null\", `${FENCE}json\\n${truncated}\\n${FENCE}`]) {\n    const h = harness([ok(body)]);\n    const result = await h.intake.processDocument(document(\"DOC-9020\"));\n    assert.equal(result.outcome, \"manual_review\", `stored ${JSON.stringify(body.slice(0, 40))}`);\n    assert.deepEqual(h.saved, []);\n    assert.deepEqual(h.reviews, [{ documentId: \"DOC-9020\", reason: \"invalid_json\", fields: [], attempts: 1 }]);\n    assert.equal(h.calls.length, 1, \"invalid output must not be retried\");\n  }\n});\n\ntest(\"a missing or null required field is not filled in\", async () => {\n  const { hazmat: _h, ...noHazmat } = VALID;\n  const { pieces: _p, ...noPieces } = VALID;\n  void _h;\n  void _p;\n  await expectInvalidFields(noHazmat, [\"hazmat\"], \"missing hazmat\");\n  await expectInvalidFields(noPieces, [\"pieces\"], \"missing pieces\");\n  await expectInvalidFields({ ...VALID, shipment_id: null }, [\"shipment_id\"], \"null shipment_id\");\n});\n\ntest(\"values that would need guessing are not repaired\", async () => {\n  await expectInvalidFields({ ...VALID, weight_kg: \"12,500 kg\" }, [\"weight_kg\"], \"weight with units\");\n  await expectInvalidFields({ ...VALID, weight_kg: \"12,500\" }, [\"weight_kg\"], \"weight with a thousands separator\");\n  await expectInvalidFields({ ...VALID, pieces: \"40 cartons\" }, [\"pieces\"], \"pieces with a unit\");\n  await expectInvalidFields({ ...VALID, hazmat: \"no\" }, [\"hazmat\"], \"hazmat as text\");\n  await expectInvalidFields({ ...VALID, hazmat: \"true\" }, [\"hazmat\"], \"hazmat as a string\");\n  await expectInvalidFields({ ...VALID, pickup_date: \"10/01/2026\" }, [\"pickup_date\"], \"pickup date in another format\");\n  await expectInvalidFields({ ...VALID, delivery_date: \"3 Oct 2026\" }, [\"delivery_date\"], \"delivery date in another format\");\n});\n\ntest(\"out-of-range and impossible values are not stored or clamped\", async () => {\n  await expectInvalidFields({ ...VALID, pieces: 0 }, [\"pieces\"], \"zero pieces\");\n  await expectInvalidFields({ ...VALID, pieces: 1000 }, [\"pieces\"], \"1000 pieces\");\n  await expectInvalidFields({ ...VALID, pieces: 2.5 }, [\"pieces\"], \"fractional pieces\");\n  await expectInvalidFields({ ...VALID, weight_kg: 0 }, [\"weight_kg\"], \"zero weight\");\n  await expectInvalidFields({ ...VALID, weight_kg: 30000.5 }, [\"weight_kg\"], \"weight over 30000\");\n  await expectInvalidFields({ ...VALID, pickup_date: \"2026-02-30\" }, [\"pickup_date\"], \"impossible date\");\n  await expectInvalidFields({ ...VALID, delivery_date: \"2026-09-30\" }, [\"delivery_date\"], \"delivery before pickup\");\n  await expectInvalidFields({ ...VALID, carrier_scac: \"qrvl\" }, [\"carrier_scac\"], \"lowercase SCAC\");\n  await expectInvalidFields({ ...VALID, carrier_scac: \"QRVLX\" }, [\"carrier_scac\"], \"five-letter SCAC\");\n  await expectInvalidFields({ ...VALID, shipment_id: \"SHP-31001\" }, [\"shipment_id\"], \"short shipment id\");\n  await expectInvalidFields({ ...VALID, pieces: 0, hazmat: \"no\" }, [\"pieces\", \"hazmat\"], \"two invalid fields\");\n});\n\ntest(\"persistent rate limiting stops after three attempts and goes to manual review\", async () => {\n  const limited = status(429, { \"retry-after\": \"1\" });\n  const h = harness([limited, limited, limited, limited, limited, limited, ok(VALID)]);\n  const result = await h.intake.processDocument(document(\"DOC-9030\"));\n  assert.equal(h.calls.length, 3, `the provider was called ${h.calls.length} times`);\n  assert.deepEqual(result, { documentId: \"DOC-9030\", outcome: \"manual_review\", attempts: 3 });\n  assert.deepEqual(h.reviews, [{ documentId: \"DOC-9030\", reason: \"provider_failed\", fields: [], attempts: 3 }]);\n  assert.deepEqual(h.saved, []);\n});\n\ntest(\"server errors and timeouts are retried, and a success on the third attempt is stored\", async () => {\n  const h = harness([status(502), TIMEOUT, ok(VALID)]);\n  const result = await h.intake.processDocument(document(\"DOC-9040\"));\n  assert.deepEqual(result, { documentId: \"DOC-9040\", outcome: \"stored\", attempts: 3 });\n  assert.deepEqual(h.saved, [{ documentId: \"DOC-9040\", record: VALID }]);\n  assert.deepEqual(h.reviews, []);\n});\n\ntest(\"a 4xx response other than 429 is not retried\", async () => {\n  for (const code of [400, 401, 422]) {\n    const h = harness([status(code), ok(VALID)]);\n    const result = await h.intake.processDocument(document(\"DOC-9050\"));\n    assert.equal(h.calls.length, 1, `HTTP ${code} was retried`);\n    assert.deepEqual(result, { documentId: \"DOC-9050\", outcome: \"manual_review\", attempts: 1 });\n    assert.deepEqual(h.reviews, [{ documentId: \"DOC-9050\", reason: \"provider_failed\", fields: [], attempts: 1 }]);\n    assert.deepEqual(h.waits, []);\n  }\n});\n\ntest(\"a 429 waits for the Retry-After seconds before the next attempt\", async () => {\n  const h = harness([status(429, { \"retry-after\": \"12\" }), status(429, { \"retry-after\": \"3\" }), ok(VALID)]);\n  const result = await h.intake.processDocument(document(\"DOC-9060\"));\n  assert.deepEqual(h.waits, [12000, 3000]);\n  assert.deepEqual(result, { documentId: \"DOC-9060\", outcome: \"stored\", attempts: 3 });\n});\n\ntest(\"server errors, timeouts and a 429 without Retry-After back off 1000 then 2000 ms, with no wait after the last attempt\", async () => {\n  const h = harness([status(503), TIMEOUT, status(500)]);\n  const result = await h.intake.processDocument(document(\"DOC-9070\"));\n  assert.deepEqual(h.waits, [1000, 2000]);\n  assert.deepEqual(result, { documentId: \"DOC-9070\", outcome: \"manual_review\", attempts: 3 });\n  assert.deepEqual(h.reviews, [{ documentId: \"DOC-9070\", reason: \"provider_failed\", fields: [], attempts: 3 }]);\n\n  const h2 = harness([status(429), ok(VALID)]);\n  await h2.intake.processDocument(document(\"DOC-9071\"));\n  assert.deepEqual(h2.waits, [1000]);\n  assert.equal(h2.saved.length, 1);\n});\n\ntest(\"a batch continues past failing documents and returns one result per document in order\", async () => {\n  const pretty = JSON.stringify({ ...VALID, shipment_id: \"SHP-310081\" }, null, 2);\n  const h = harness({\n    \"DOC-9081\": [ok(`${FENCE}json\\n${pretty}\\n${FENCE}`)],\n    \"DOC-9082\": [ok(\"{\\\"shipment_id\\\": \\\"SHP-310082\\\", \\\"pieces\\\": \")],\n    \"DOC-9083\": [status(400)],\n    \"DOC-9084\": [status(500), TIMEOUT, status(503)],\n    \"DOC-9085\": [ok({ ...VALID, shipment_id: \"SHP-310085\", weight_kg: 31000 })],\n    \"DOC-9086\": [ok({ ...VALID, shipment_id: \"SHP-310086\" })],\n  });\n  const ids = [\"DOC-9081\", \"DOC-9082\", \"DOC-9083\", \"DOC-9084\", \"DOC-9085\", \"DOC-9086\"];\n  const results = await h.intake.runBatch(ids.map(document));\n  assert.deepEqual(results.map((r) => [r.documentId, r.outcome]), [\n    [\"DOC-9081\", \"stored\"],\n    [\"DOC-9082\", \"manual_review\"],\n    [\"DOC-9083\", \"manual_review\"],\n    [\"DOC-9084\", \"manual_review\"],\n    [\"DOC-9085\", \"manual_review\"],\n    [\"DOC-9086\", \"stored\"],\n  ]);\n  assert.deepEqual(h.saved.map((s) => s.documentId), [\"DOC-9081\", \"DOC-9086\"]);\n  assert.deepEqual(h.reviews.map((r) => [r.documentId, r.reason]), [\n    [\"DOC-9082\", \"invalid_json\"],\n    [\"DOC-9083\", \"provider_failed\"],\n    [\"DOC-9084\", \"provider_failed\"],\n    [\"DOC-9085\", \"invalid_fields\"],\n  ]);\n});\n";

export const REFERENCE_VALIDATE = "import { SHIPMENT_FIELDS } from \"./schema.js\";\n\nconst FENCE = /^`{3}(?:json)?[ \\t]*\\r?\\n([\\s\\S]*?)\\r?\\n?`{3}$/i;\nconst DATE = /^(\\d{4})-(\\d{2})-(\\d{2})$/;\n\n/** Removes a surrounding markdown code fence. Anything else around the JSON is left for JSON.parse to reject. */\nfunction stripFence(body) {\n  const trimmed = body.trim();\n  const match = FENCE.exec(trimmed);\n  return match ? match[1].trim() : trimmed;\n}\n\n/** Parses the provider body into an object, or null when it is not a JSON object even after removing a fence. */\nexport function parseModelOutput(body) {\n  try {\n    const value = JSON.parse(stripFence(String(body)));\n    return value !== null && typeof value === \"object\" && !Array.isArray(value) ? value : null;\n  } catch {\n    return null;\n  }\n}\n\nfunction isCalendarDate(value) {\n  if (typeof value !== \"string\") return false;\n  const m = DATE.exec(value);\n  if (!m) return false;\n  const [y, mo, d] = [Number(m[1]), Number(m[2]), Number(m[3])];\n  const date = new Date(Date.UTC(y, mo - 1, d));\n  return date.getUTCFullYear() === y && date.getUTCMonth() === mo - 1 && date.getUTCDate() === d;\n}\n\n/** The only repair allowed on values: a plain decimal string (\"12\", \"840.5\") becomes a number. */\nfunction plainNumber(value, integerOnly) {\n  if (typeof value === \"number\") return value;\n  if (typeof value === \"string\" && (integerOnly ? /^\\d+$/ : /^\\d+(\\.\\d+)?$/).test(value)) return Number(value);\n  return value;\n}\n\nconst CHECKS = {\n  shipment_id: (v) => typeof v === \"string\" && /^SHP-\\d{6}$/.test(v),\n  carrier_scac: (v) => typeof v === \"string\" && /^[A-Z]{2,4}$/.test(v),\n  pickup_date: (v) => isCalendarDate(v),\n  delivery_date: (v, record) => v === null || (isCalendarDate(v) && (!isCalendarDate(record.pickup_date) || v >= record.pickup_date)),\n  pieces: (v) => Number.isInteger(v) && v >= 1 && v <= 999,\n  weight_kg: (v) => typeof v === \"number\" && Number.isFinite(v) && v > 0 && v <= 30000,\n  hazmat: (v) => typeof v === \"boolean\",\n};\n\n/**\n * Validates a parsed model object against SHIPMENT_FIELDS after the safe repairs.\n * Returns { ok: true, record } with exactly the schema fields, or { ok: false, fields } naming\n * every missing or invalid field in schema order.\n */\nexport function validateShipment(raw) {\n  const record = {};\n  for (const field of SHIPMENT_FIELDS) {\n    let value = raw[field.name];\n    if (value === undefined && !field.required) value = null;\n    if (field.name === \"pieces\") value = plainNumber(value, true);\n    if (field.name === \"weight_kg\") value = plainNumber(value, false);\n    record[field.name] = value;\n  }\n  const fields = SHIPMENT_FIELDS.filter((f) => record[f.name] === undefined || !CHECKS[f.name](record[f.name], record)).map((f) => f.name);\n  return fields.length ? { ok: false, fields } : { ok: true, record };\n}\n";

export const REFERENCE_INTAKE = "import { buildExtractionRequest } from \"./prompt.js\";\nimport { parseModelOutput, validateShipment } from \"./validate.js\";\n\nexport const MAX_ATTEMPTS = 3;\nconst BACKOFF_MS = [1000, 2000];\n\nfunction retryAfterMs(headers) {\n  const raw = headers?.[\"retry-after\"];\n  return typeof raw === \"string\" && /^\\d+$/.test(raw.trim()) ? Number(raw.trim()) * 1000 : null;\n}\n\n/**\n * Calls the provider with at most MAX_ATTEMPTS attempts. 429, 5xx and rejected sends\n * (timeouts, connection errors) are retried; any other status is final.\n * Returns { response, attempts } or { failed: true, attempts }.\n */\nasync function callProvider(transport, sleep, request) {\n  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {\n    let response = null;\n    try {\n      response = await transport.send(request);\n    } catch {\n      response = null;\n    }\n    if (response && response.status === 200) return { response, attempts: attempt };\n    const retryable = response === null || response.status === 429 || response.status >= 500;\n    if (!retryable || attempt === MAX_ATTEMPTS) return { failed: true, attempts: attempt };\n    const wait = response && response.status === 429 ? retryAfterMs(response.headers) : null;\n    await sleep(wait ?? BACKOFF_MS[attempt - 1]);\n  }\n  return { failed: true, attempts: MAX_ATTEMPTS };\n}\n\n/**\n * Document intake: sends each document to the extraction provider and stores the shipment record.\n *\n * deps.transport.send(request) -> Promise<{ status, headers, body }>; rejects on a timeout or connection error.\n * deps.store.save(documentId, record)\n * deps.reviewQueue.add({ documentId, reason, fields, attempts })\n * deps.sleep(ms) -> Promise<void>\n */\nexport function createIntake({ transport, store, reviewQueue, sleep }) {\n  function toReview(documentId, reason, fields, attempts) {\n    reviewQueue.add({ documentId, reason, fields, attempts });\n    return { documentId, outcome: \"manual_review\", attempts };\n  }\n\n  async function processDocument(document) {\n    const call = await callProvider(transport, sleep, buildExtractionRequest(document));\n    if (call.failed) return toReview(document.id, \"provider_failed\", [], call.attempts);\n    const parsed = parseModelOutput(call.response.body);\n    if (!parsed) return toReview(document.id, \"invalid_json\", [], call.attempts);\n    const checked = validateShipment(parsed);\n    if (!checked.ok) return toReview(document.id, \"invalid_fields\", checked.fields, call.attempts);\n    store.save(document.id, checked.record);\n    return { documentId: document.id, outcome: \"stored\", attempts: call.attempts };\n  }\n\n  async function runBatch(documents) {\n    const results = [];\n    for (const document of documents) {\n      results.push(await processDocument(document));\n    }\n    return results;\n  }\n\n  return { processDocument, runBatch };\n}\n";

export const WRONG_UNBOUNDED_429_INTAKE = "import { buildExtractionRequest } from \"./prompt.js\";\nimport { parseModelOutput, validateShipment } from \"./validate.js\";\n\nexport const MAX_ATTEMPTS = 3;\nconst BACKOFF_MS = [1000, 2000];\n\nfunction retryAfterMs(headers) {\n  const raw = headers?.[\"retry-after\"];\n  return typeof raw === \"string\" && /^\\d+$/.test(raw.trim()) ? Number(raw.trim()) * 1000 : null;\n}\n\n/**\n * Calls the provider. Rate limits are temporary, so a 429 is always retried after its\n * Retry-After delay. 5xx and rejected sends are retried up to MAX_ATTEMPTS.\n */\nasync function callProvider(transport, sleep, request) {\n  let attempt = 0;\n  while (true) {\n    attempt++;\n    let response = null;\n    try {\n      response = await transport.send(request);\n    } catch {\n      response = null;\n    }\n    if (response && response.status === 200) return { response, attempts: attempt };\n    if (response && response.status === 429) {\n      await sleep(retryAfterMs(response.headers) ?? BACKOFF_MS[0]);\n      continue;\n    }\n    const retryable = response === null || response.status >= 500;\n    if (!retryable || attempt >= MAX_ATTEMPTS) return { failed: true, attempts: attempt };\n    await sleep(BACKOFF_MS[Math.min(attempt - 1, BACKOFF_MS.length - 1)]);\n  }\n}\n\n/**\n * Document intake: sends each document to the extraction provider and stores the shipment record.\n *\n * deps.transport.send(request) -> Promise<{ status, headers, body }>; rejects on a timeout or connection error.\n * deps.store.save(documentId, record)\n * deps.reviewQueue.add({ documentId, reason, fields, attempts })\n * deps.sleep(ms) -> Promise<void>\n */\nexport function createIntake({ transport, store, reviewQueue, sleep }) {\n  function toReview(documentId, reason, fields, attempts) {\n    reviewQueue.add({ documentId, reason, fields, attempts });\n    return { documentId, outcome: \"manual_review\", attempts };\n  }\n\n  async function processDocument(document) {\n    const call = await callProvider(transport, sleep, buildExtractionRequest(document));\n    if (call.failed) return toReview(document.id, \"provider_failed\", [], call.attempts);\n    const parsed = parseModelOutput(call.response.body);\n    if (!parsed) return toReview(document.id, \"invalid_json\", [], call.attempts);\n    const checked = validateShipment(parsed);\n    if (!checked.ok) return toReview(document.id, \"invalid_fields\", checked.fields, call.attempts);\n    store.save(document.id, checked.record);\n    return { documentId: document.id, outcome: \"stored\", attempts: call.attempts };\n  }\n\n  async function runBatch(documents) {\n    const results = [];\n    for (const document of documents) {\n      results.push(await processDocument(document));\n    }\n    return results;\n  }\n\n  return { processDocument, runBatch };\n}\n";

export const WRONG_IGNORES_RETRY_AFTER_INTAKE = "import { buildExtractionRequest } from \"./prompt.js\";\nimport { parseModelOutput, validateShipment } from \"./validate.js\";\n\nexport const MAX_ATTEMPTS = 3;\nconst BACKOFF_MS = [1000, 2000];\n\n/**\n * Calls the provider with at most MAX_ATTEMPTS attempts. 429, 5xx and rejected sends\n * (timeouts, connection errors) are retried with exponential backoff; any other status is final.\n * Returns { response, attempts } or { failed: true, attempts }.\n */\nasync function callProvider(transport, sleep, request) {\n  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {\n    let response = null;\n    try {\n      response = await transport.send(request);\n    } catch {\n      response = null;\n    }\n    if (response && response.status === 200) return { response, attempts: attempt };\n    const retryable = response === null || response.status === 429 || response.status >= 500;\n    if (!retryable || attempt === MAX_ATTEMPTS) return { failed: true, attempts: attempt };\n    await sleep(BACKOFF_MS[attempt - 1]);\n  }\n  return { failed: true, attempts: MAX_ATTEMPTS };\n}\n\n/**\n * Document intake: sends each document to the extraction provider and stores the shipment record.\n *\n * deps.transport.send(request) -> Promise<{ status, headers, body }>; rejects on a timeout or connection error.\n * deps.store.save(documentId, record)\n * deps.reviewQueue.add({ documentId, reason, fields, attempts })\n * deps.sleep(ms) -> Promise<void>\n */\nexport function createIntake({ transport, store, reviewQueue, sleep }) {\n  function toReview(documentId, reason, fields, attempts) {\n    reviewQueue.add({ documentId, reason, fields, attempts });\n    return { documentId, outcome: \"manual_review\", attempts };\n  }\n\n  async function processDocument(document) {\n    const call = await callProvider(transport, sleep, buildExtractionRequest(document));\n    if (call.failed) return toReview(document.id, \"provider_failed\", [], call.attempts);\n    const parsed = parseModelOutput(call.response.body);\n    if (!parsed) return toReview(document.id, \"invalid_json\", [], call.attempts);\n    const checked = validateShipment(parsed);\n    if (!checked.ok) return toReview(document.id, \"invalid_fields\", checked.fields, call.attempts);\n    store.save(document.id, checked.record);\n    return { documentId: document.id, outcome: \"stored\", attempts: call.attempts };\n  }\n\n  async function runBatch(documents) {\n    const results = [];\n    for (const document of documents) {\n      results.push(await processDocument(document));\n    }\n    return results;\n  }\n\n  return { processDocument, runBatch };\n}\n";

export const WRONG_UNSAFE_REPAIR_VALIDATE = "import { SHIPMENT_FIELDS } from \"./schema.js\";\n\nconst FENCE = /^`{3}(?:json)?[ \\t]*\\r?\\n([\\s\\S]*?)\\r?\\n?`{3}$/i;\nconst DATE = /^(\\d{4})-(\\d{2})-(\\d{2})$/;\nconst US_DATE = /^(\\d{2})\\/(\\d{2})\\/(\\d{4})$/;\n\nfunction stripFence(body) {\n  const trimmed = body.trim();\n  const match = FENCE.exec(trimmed);\n  return match ? match[1].trim() : trimmed;\n}\n\n/** Parses the provider body into an object, or null when it is not a JSON object even after removing a fence. */\nexport function parseModelOutput(body) {\n  try {\n    const value = JSON.parse(stripFence(String(body)));\n    return value !== null && typeof value === \"object\" && !Array.isArray(value) ? value : null;\n  } catch {\n    return null;\n  }\n}\n\nfunction isCalendarDate(value) {\n  if (typeof value !== \"string\") return false;\n  const m = DATE.exec(value);\n  if (!m) return false;\n  const [y, mo, d] = [Number(m[1]), Number(m[2]), Number(m[3])];\n  const date = new Date(Date.UTC(y, mo - 1, d));\n  return date.getUTCFullYear() === y && date.getUTCMonth() === mo - 1 && date.getUTCDate() === d;\n}\n\n/** Models format numbers like the document does (\"1,250 kg\"), so keep the digits. */\nfunction toNumber(value) {\n  if (typeof value === \"string\" && /\\d/.test(value)) return Number(value.replace(/[^0-9.]/g, \"\"));\n  return value;\n}\n\nfunction toBoolean(value) {\n  if (typeof value !== \"string\") return value;\n  const v = value.trim().toLowerCase();\n  if ([\"true\", \"yes\", \"y\"].includes(v)) return true;\n  if ([\"false\", \"no\", \"n\", \"none\"].includes(v)) return false;\n  return value;\n}\n\nfunction toIsoDate(value) {\n  const m = typeof value === \"string\" ? US_DATE.exec(value.trim()) : null;\n  return m ? `${m[3]}-${m[1]}-${m[2]}` : value;\n}\n\nconst CHECKS = {\n  shipment_id: (v) => typeof v === \"string\" && /^SHP-\\d{6}$/.test(v),\n  carrier_scac: (v) => typeof v === \"string\" && /^[A-Z]{2,4}$/.test(v),\n  pickup_date: (v) => isCalendarDate(v),\n  delivery_date: (v, record) => v === null || (isCalendarDate(v) && (!isCalendarDate(record.pickup_date) || v >= record.pickup_date)),\n  pieces: (v) => Number.isInteger(v) && v >= 1 && v <= 999,\n  weight_kg: (v) => typeof v === \"number\" && Number.isFinite(v) && v > 0 && v <= 30000,\n  hazmat: (v) => typeof v === \"boolean\",\n};\n\n/**\n * Validates a parsed model object against SHIPMENT_FIELDS after normalizing common formats.\n * Returns { ok: true, record } with exactly the schema fields, or { ok: false, fields }.\n */\nexport function validateShipment(raw) {\n  const record = {};\n  for (const field of SHIPMENT_FIELDS) {\n    let value = raw[field.name];\n    if (value === undefined && !field.required) value = null;\n    if (field.type === \"integer\" || field.type === \"number\") value = toNumber(value);\n    if (field.type === \"boolean\") value = toBoolean(value);\n    if (field.name.endsWith(\"_date\")) value = toIsoDate(value);\n    record[field.name] = value;\n  }\n  const fields = SHIPMENT_FIELDS.filter((f) => record[f.name] === undefined || !CHECKS[f.name](record[f.name], record)).map((f) => f.name);\n  return fields.length ? { ok: false, fields } : { ok: true, record };\n}\n";

export const WRONG_TYPE_ONLY_VALIDATE = "import { SHIPMENT_FIELDS } from \"./schema.js\";\n\nconst FENCE = /^`{3}(?:json)?[ \\t]*\\r?\\n([\\s\\S]*?)\\r?\\n?`{3}$/i;\n\nfunction stripFence(body) {\n  const trimmed = body.trim();\n  const match = FENCE.exec(trimmed);\n  return match ? match[1].trim() : trimmed;\n}\n\n/** Parses the provider body into an object, or null when it is not a JSON object even after removing a fence. */\nexport function parseModelOutput(body) {\n  try {\n    const value = JSON.parse(stripFence(String(body)));\n    return value !== null && typeof value === \"object\" && !Array.isArray(value) ? value : null;\n  } catch {\n    return null;\n  }\n}\n\nfunction plainNumber(value, integerOnly) {\n  if (typeof value === \"number\") return value;\n  if (typeof value === \"string\" && (integerOnly ? /^\\d+$/ : /^\\d+(\\.\\d+)?$/).test(value)) return Number(value);\n  return value;\n}\n\nconst TYPE_CHECKS = {\n  string: (v) => typeof v === \"string\",\n  integer: (v) => Number.isInteger(v),\n  number: (v) => typeof v === \"number\" && Number.isFinite(v),\n  boolean: (v) => typeof v === \"boolean\",\n};\n\n/**\n * Validates a parsed model object against the types in SHIPMENT_FIELDS.\n * Returns { ok: true, record } with exactly the schema fields, or { ok: false, fields }.\n */\nexport function validateShipment(raw) {\n  const record = {};\n  const fields = [];\n  for (const field of SHIPMENT_FIELDS) {\n    let value = raw[field.name];\n    if (field.type === \"integer\") value = plainNumber(value, true);\n    if (field.type === \"number\") value = plainNumber(value, false);\n    if ((value === undefined || value === null) && !field.required) {\n      record[field.name] = null;\n      continue;\n    }\n    if (value === undefined || value === null || !TYPE_CHECKS[field.type](value)) fields.push(field.name);\n    record[field.name] = value;\n  }\n  return fields.length ? { ok: false, fields } : { ok: true, record };\n}\n";

export const WRONG_RETRIES_4XX_INTAKE = "import { buildExtractionRequest } from \"./prompt.js\";\nimport { parseModelOutput, validateShipment } from \"./validate.js\";\n\nexport const MAX_ATTEMPTS = 3;\nconst BACKOFF_MS = [1000, 2000];\n\nfunction retryAfterMs(headers) {\n  const raw = headers?.[\"retry-after\"];\n  return typeof raw === \"string\" && /^\\d+$/.test(raw.trim()) ? Number(raw.trim()) * 1000 : null;\n}\n\n/**\n * Calls the provider with at most MAX_ATTEMPTS attempts. Any failed attempt is retried,\n * since provider errors are usually transient.\n * Returns { response, attempts } or { failed: true, attempts }.\n */\nasync function callProvider(transport, sleep, request) {\n  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {\n    let response = null;\n    try {\n      response = await transport.send(request);\n    } catch {\n      response = null;\n    }\n    if (response && response.status === 200) return { response, attempts: attempt };\n    if (attempt === MAX_ATTEMPTS) return { failed: true, attempts: attempt };\n    const wait = response && response.status === 429 ? retryAfterMs(response.headers) : null;\n    await sleep(wait ?? BACKOFF_MS[attempt - 1]);\n  }\n  return { failed: true, attempts: MAX_ATTEMPTS };\n}\n\n/**\n * Document intake: sends each document to the extraction provider and stores the shipment record.\n *\n * deps.transport.send(request) -> Promise<{ status, headers, body }>; rejects on a timeout or connection error.\n * deps.store.save(documentId, record)\n * deps.reviewQueue.add({ documentId, reason, fields, attempts })\n * deps.sleep(ms) -> Promise<void>\n */\nexport function createIntake({ transport, store, reviewQueue, sleep }) {\n  function toReview(documentId, reason, fields, attempts) {\n    reviewQueue.add({ documentId, reason, fields, attempts });\n    return { documentId, outcome: \"manual_review\", attempts };\n  }\n\n  async function processDocument(document) {\n    const call = await callProvider(transport, sleep, buildExtractionRequest(document));\n    if (call.failed) return toReview(document.id, \"provider_failed\", [], call.attempts);\n    const parsed = parseModelOutput(call.response.body);\n    if (!parsed) return toReview(document.id, \"invalid_json\", [], call.attempts);\n    const checked = validateShipment(parsed);\n    if (!checked.ok) return toReview(document.id, \"invalid_fields\", checked.fields, call.attempts);\n    store.save(document.id, checked.record);\n    return { documentId: document.id, outcome: \"stored\", attempts: call.attempts };\n  }\n\n  async function runBatch(documents) {\n    const results = [];\n    for (const document of documents) {\n      results.push(await processDocument(document));\n    }\n    return results;\n  }\n\n  return { processDocument, runBatch };\n}\n";
